def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    flipped_string = ""
    for char in string:
        if 'a' <= char <= 'z':
            flipped_string += chr(ord(char) - 32)  # Convert to uppercase
        elif 'A' <= char <= 'Z':
            flipped_string += chr(ord(char) + 32)  # Convert to lowercase
        else:
            flipped_string += char  # Keep non-alphabetic characters as they are
    return flipped_string

